from __future__ import annotations

import hashlib
import os
import pickle
import pandas as pd
import json
from pathlib import Path
from typing import Any
from fastapi import FastAPI
from pydantic import BaseModel

# Paths to artifacts generated by train.py
MODEL_PATH = Path(os.getenv("MODEL_PATH", Path(__file__).with_name("pipeline.bin")))
DEFAULTS_PATH = Path(
    os.getenv("DEFAULTS_PATH", Path(__file__).with_name("feature_defaults.json"))
)
with MODEL_PATH.open("rb") as model_file:
    pipeline = pickle.load(model_file)

FEATURE_DEFAULTS: dict[str, float] = json.loads(
    DEFAULTS_PATH.read_text(encoding="utf-8")
)

MODEL_SHA256 = hashlib.sha256(MODEL_PATH.read_bytes()).hexdigest()
FEATURE_DEFAULTS_SHA256 = hashlib.sha256(DEFAULTS_PATH.read_bytes()).hexdigest()

FEATURES = [
    "battery_power", "blue", "clock_speed", "dual_sim", "fc", "four_g",
    "int_memory", "m_dep", "mobile_wt", "n_cores", "pc", "px_height",
    "px_width", "ram", "sc_h", "sc_w", "talk_time", "three_g",
    "touch_screen", "wifi"
]

PRICE_LABELS = {
    0: "Low Cost",
    1: "Intermediate-Low Cost",
    2: "Intermediate-High Cost",
    3: "High Cost",
}

app = FastAPI(title="Mobile Price Classification API for ML Zoomcamp 2026 Midterm Project")

# Defining MobileSpecs class using BaseModel from pydantic as base
class MobileSpecs(BaseModel):
    battery_power: float | None = None
    blue: int | None = None
    clock_speed: float | None = None
    dual_sim: int | None = None
    fc: float | None = None
    four_g: int | None = None
    int_memory: float | None = None
    m_dep: float | None = None
    mobile_wt: float | None = None
    n_cores: int | None = None
    pc: float | None = None
    px_height: float | None = None
    px_width: float | None = None
    ram: float | None = None
    sc_h: float | None = None
    sc_w: float | None = None
    talk_time: float | None = None
    three_g: int | None = None
    touch_screen: int | None = None
    wifi: int | None = None

def prepare_features(specs: dict[str, Any]) -> pd.DataFrame:
    """Fills missing values with training medians and preserves column order."""
    record = {}
    for feature in FEATURES:
        val = specs.get(feature)
        # Fallback to training median if value is missing or physically invalid (0)
        if val is None or (feature in ("px_height", "sc_w") and val <= 0):
            record[feature] = FEATURE_DEFAULTS[feature]
        else:
            record[feature] = val

    return pd.DataFrame([record], columns=FEATURES)

@app.get("/health")
def health() -> dict[str, Any]:
    return {
        "status": "ok",
        "model_sha256": MODEL_SHA256,
        "feature_defaults_sha256": FEATURE_DEFAULTS_SHA256,
    }


@app.post("/predict")
def predict(mobile: MobileSpecs) -> dict[str, Any]:
    X_input = prepare_features(mobile.model_dump())

    # Multiclass probabilities across the 4 price tiers (0, 1, 2, 3)
    probs = pipeline.predict_proba(X_input)[0]
    predicted_class = int(probs.argmax())

    return {
        "price_range": predicted_class,
        "price_label": PRICE_LABELS[predicted_class],
        "confidence": round(float(probs[predicted_class]), 6),
        "class_probabilities": {
            str(i): round(float(p), 6) for i, p in enumerate(probs)
        },
    }
